const { prisma } = await app("lib/prisma.ts");
const { updateWorkspaceSettingsAction } = await app("lib/actions/workspace-settings.ts");
const { requireWorkspaceAdmin } = await app("lib/workspace.ts");

// Create a user and workspace with admin membership
const user = await prisma.user.create({ data: { email: "admin@example.com", name: "Admin User", passwordHash: "hash" } });
const workspace = await prisma.workspace.create({ data: { name: "Test Workspace", slug: "test-workspace", webhookSecret: "secret" } });
await prisma.membership.create({ data: { userId: user.id, workspaceId: workspace.id, role: "ADMIN" } });

// Set session as signed in user
set_session({ user: { id: user.id, email: user.email } });

// Helper to create FormData
function createFormData(data) {
  const fd = new FormData();
  for (const [key, value] of Object.entries(data)) {
    if (value !== null && value !== undefined) {
      fd.set(key, value);
    }
  }
  return fd;
}

